const STAGE="open";
const readRequest=()=>{const r=$input.first().json.request;return typeof r==='string'?JSON.parse(r):r;};
if (STAGE==='open') {
  const c=readRequest();
  if (!c) return [];
  if (!['preview','start'].includes(c.kind)||!['football','basketball','f1'].includes(c.sport)||!Number.isFinite(Date.parse(c.at))) throw new Error('Invalid alert job');
  c.phase='validate'; c.checks=0;
  c.check_at=new Date(Math.max(Date.now(),Date.parse(c.due_at)-(c.kind==='preview'?180000:45000))).toISOString();
  c.request_url=c.sport==='football'?'https://api.football-data.org/v4/matches/'+c.provider_id:
    c.sport==='basketball'?'https://api.balldontlie.io/v1/games/'+c.provider_id:
    `https://api.jolpi.ca/ergast/f1/${c.season}/${c.round}/races/?limit=100`;
  return [{json:c}];
}
if (STAGE==='unwrap') return [{json:readRequest()}];
if (STAGE==='response') {
  const c=JSON.parse(JSON.stringify($('Unpack API slot').last().json));
  const r=$input.first().json.body||$input.first().json;
  const unavailable=Boolean($input.first().json.error||r.error);
  const finish=(step)=>[{json:{...c,step}}];
  const abort=(state,reason)=>[{json:{...c,step:'stop',finish_state:state,reason}}];
  const next=(phase,url)=>{c.phase=phase;c.request_url=url;return finish('request');};
  const day=d=>new Date(d).toISOString().slice(0,10);
  if(c.phase==='validate') {
    if(unavailable) return abort('failed','Provider unavailable during schedule recheck. No stale alert was sent.');
    let at, valid;
    if(c.sport==='football') {
      valid=String(r.id)===c.provider_id&&['SCHEDULED','TIMED','IN_PLAY','PAUSED'].includes(r.status);
      at=r.utcDate;
      if(r.homeTeam?.name&&r.awayTeam?.name){c.home=r.homeTeam.name;c.away=r.awayTeam.name;c.title=c.home+' vs '+c.away;
        c.participants=[r.homeTeam.name,r.homeTeam.shortName,r.homeTeam.tla,r.awayTeam.name,r.awayTeam.shortName,r.awayTeam.tla].filter(Boolean);}
      if(c.kind==='preview'&&!['SCHEDULED','TIMED'].includes(r.status)) valid=false;
    } else if(c.sport==='basketball') {
      const g=r.data;
      if(!g) return abort('failed','NBA game missing from provider response.');
      const state=g.status_state;
      valid=String(g.id)===c.provider_id&&!g.postponed&&!/final|postpon|cancel|suspend|abandon|delay/i.test(g.status||'')&&
        (!state||['scheduled','in_progress'].includes(state));
      if(c.kind==='preview'&&((state&&state!=='scheduled')||Number(g.period||0)>0))valid=false;
      at=g.datetime;
      if(g.home_team?.full_name&&g.visitor_team?.full_name){c.home=g.home_team.full_name;c.away=g.visitor_team.full_name;c.title=c.home+' vs '+c.away;
        c.participants=[g.home_team.full_name,g.home_team.name,g.home_team.abbreviation,g.visitor_team.full_name,g.visitor_team.name,g.visitor_team.abbreviation].filter(Boolean);}
    } else {
      const race=r.MRData?.RaceTable?.Races?.find(x=>String(x.season)===c.season&&String(x.round)===c.round);
      const session=c.session==='Race'?race:race?.Qualifying;
      valid=Boolean(session?.date&&session?.time);
      at=valid?session.date+'T'+session.time:null;
    }
    if(!valid) return abort('cancelled','Event is no longer scheduled or the session cannot be verified.');
    const time=typeof at==='string'&&at.includes('T')?Date.parse(at):NaN;
    if(!Number.isFinite(time))return abort('failed','Provider has no confirmed start time.');
    c.at=new Date(time).toISOString();
    c.due_at=new Date(time-(c.kind==='preview'?1800000:0)).toISOString();
    const due=Date.parse(c.due_at), now=Date.now();
    if(due<now-(c.kind==='preview'?5:3)*60000)return abort('cancelled','Alert window passed; no late alert was sent.');
    if(due>now+12*3600000)return abort('failed','Event moved beyond this worker horizon; the planner will reconsider it.');
    const lead=c.kind==='preview'?180000:45000;
    if(due>now+lead+15000) {
      if(++c.checks>8)return abort('failed','Too many schedule changes; the next planner run can reconsider this event.');
      c.check_at=new Date(due-lead).toISOString();
      return finish('wait');
    }
    if(c.kind==='start')return finish('compose');
    c.form={};
    if(c.sport==='football')return next('home_form',`https://api.football-data.org/v4/teams/${c.home_id}/matches?status=FINISHED&limit=100&dateFrom=${day(now-90*86400000)}&dateTo=${day(now)}`);
    if(c.sport==='basketball')return next('nba_form',`https://api.balldontlie.io/v1/games?team_ids[]=${c.home_id}&team_ids[]=${c.away_id}&start_date=${day(now-30*86400000)}&end_date=${day(now)}&per_page=100`);
    return next('f1_form',`https://api.jolpi.ca/ergast/f1/${c.season}/last/results/?limit=100`);
  }
  if(c.phase==='home_form'||c.phase==='away_form') {
    const key=c.phase==='home_form'?'home':'away';
    c.form[key]=!unavailable&&Array.isArray(r.matches)?r.matches:[];
    if(key==='home')return next('away_form',`https://api.football-data.org/v4/teams/${c.away_id}/matches?status=FINISHED&limit=100&dateFrom=${day(Date.now()-90*86400000)}&dateTo=${day(Date.now())}`);
  } else if(c.phase==='nba_form') {
    c.form.games=!unavailable&&Array.isArray(r.data)&&r.meta?.next_cursor==null?r.data:[];
  } else if(c.phase==='f1_form') {
    c.form.race=!unavailable?r.MRData?.RaceTable?.Races?.[0]:null;
  }
  return finish('compose');
}
if (STAGE==='render') {
  const c=$input.first().json;
  const fmt=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Paris',weekday:'short',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
  const clock=fmt.format(new Date(c.at));
  let text;
  if(c.kind==='start') {
    const verb=c.sport==='football'?'Kick-off':c.sport==='basketball'?'Tip-off':c.session==='Race'?'Race start':'Qualifying start';
    text=`⏰ ${verb} reminder\n\n${c.title}\n${c.competition}\nScheduled start: ${clock} (Europe/Paris)\n\nThis reminder follows the published schedule; the actual start may differ.\n\n/reminders off — stop start reminders`;
  } else {
    const lines=[`🔎 Starts in about 30 minutes`,``,c.title,`${c.competition} · ${clock} (Europe/Paris)`];
    if(c.sport==='football'||c.sport==='basketball') {
      const summaries=[];
      for(const [side,id,name] of [['home',c.home_id,c.home],['away',c.away_id,c.away]]) {
        const games=c.sport==='football'?(c.form?.[side]||[]):(c.form?.games||[]);
        const sample=games.filter(g=>{
          if(c.sport==='football')return g.status==='FINISHED'&&[g.homeTeam?.id,g.awayTeam?.id].map(String).includes(String(id))&&Date.parse(g.utcDate)<Date.now()&&Number.isFinite(g.score?.fullTime?.home)&&Number.isFinite(g.score?.fullTime?.away);
          return (g.status_state==='final'||/^final/i.test(g.status||''))&&[g.home_team?.id,g.visitor_team?.id].map(String).includes(String(id))&&Number.isFinite(g.home_team_score)&&Number.isFinite(g.visitor_team_score);
        }).sort((a,b)=>Date.parse(b.utcDate||b.datetime||b.date)-Date.parse(a.utcDate||a.datetime||a.date)).slice(0,5);
        let wins=0,draws=0,scored=0,conceded=0;const form=[];
        for(const g of sample){
          const home=String(c.sport==='football'?g.homeTeam.id:g.home_team.id)===String(id);
          const hs=c.sport==='football'?g.score.fullTime.home:g.home_team_score,as=c.sport==='football'?g.score.fullTime.away:g.visitor_team_score;
          const a=home?hs:as,b=home?as:hs;
          scored+=a;conceded+=b;wins+=a>b?1:0;draws+=a===b?1:0;form.push(a>b?'W':a===b?'D':'L');
        }
        if(!sample.length){lines.push(``,`${name}: recent results unavailable.`);continue;}
        const n=sample.length;
        lines.push(``,`${name} — last ${n} completed games${c.sport==='basketball'?' available in the past 30 days':''}:`,`${form.join(' · ')} (newest first)`,
          `${wins}W${c.sport==='football'?' '+draws+'D':''} ${n-wins-draws}L · average ${c.sport==='football'?'goals':'points'}: ${(scored/n).toFixed(1)} for / ${(conceded/n).toFixed(1)} against`);
        summaries.push({name,n,rate:wins/n});
      }
      if(summaries.length===2&&summaries.every(s=>s.n>=3)) {
        const [a,b]=summaries;
        lines.push('',Math.abs(a.rate-b.rate)<0.15?'Recent win rates are similar, so the form sample does not point to a clear advantage.':`${a.rate>b.rate?a.name:b.name} has the stronger win rate in this recent sample. That is context rather than a prediction.`);
      }
      lines.push('','Confirmed lineups, injuries and individual players to watch are unavailable from the free data used here.');
    } else {
      if(c.circuit)lines.push('',`Circuit: ${c.circuit}${c.location?' · '+c.location:''}`);
      const race=c.form?.race;
      if(race&&race.date&&Date.parse(race.date)<Date.parse(c.at)&&Array.isArray(race.Results)) {
        const top=race.Results.slice().sort((a,b)=>Number(a.position)-Number(b.position)).slice(0,3);
        lines.push('',`Most recent completed Grand Prix: ${race.raceName}`,...top.map(r=>`${r.position}. ${r.Driver.givenName} ${r.Driver.familyName} — ${r.Constructor?.name||''}`));
      } else lines.push('','Previous race results are unavailable.');
      lines.push('',c.session==='Race'?'Watch the opening lap and tyre strategy. Grid penalties, weather and team decisions can change the race picture.':'Qualifying sets the sporting order used to determine the grid; penalties can still change starting positions.');
      lines.push('','Starting grid, weather and driver absences are not verified in this preview.');
    }
    lines.push('','/previews off — stop previews');text=lines.join('\n');
  }
  c.text=text.slice(0,3500).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  return [{json:c}];
}
if (STAGE==='recipients') {
  const c=readRequest();
  return c.recipients.map(r=>({json:{...c,recipients:undefined,chat_id:r.chat_id}}));
}
