const STAGE = 'response';

// NBA history: search recent games first, then extend only if needed.
const nbaWindows = [30, 180, 400];
const nbaMaxRequests = 8;

const nbaTime = g => Date.parse(g.datetime || g.date || '');

const nbaFinal = (g, c) => {
  const time = nbaTime(g);
  const cutoff = Math.min(
    c.form?.nba_search?.anchor || Date.now(),
    Date.parse(c.at)
  );

  return (
    g.id != null &&
    String(g.id) !== String(c.provider_id) &&
    g.season_type !== 'preseason' &&
    !g.postponed &&
    (
      g.status_state === 'final' ||
      (!g.status_state && /^final/i.test(g.status || ''))
    ) &&
    Number.isFinite(time) &&
    time < cutoff &&
    Number.isFinite(g.home_team_score) &&
    Number.isFinite(g.visitor_team_score) &&
    g.home_team_score >= 0 &&
    g.visitor_team_score >= 0 &&
    g.home_team_score !== g.visitor_team_score
  );
};

const nbaSample = (games, id, c) =>
  [...new Map(
    games
      .filter(g =>
        nbaFinal(g, c) &&
        [g.home_team?.id, g.visitor_team?.id]
          .map(String)
          .includes(String(id))
      )
      .map(g => [String(g.id), g])
  ).values()]
    .sort((a, b) => nbaTime(b) - nbaTime(a))
    .slice(0, 5);

const nbaUrl = (c, cursor) => {
  const s = c.form.nba_search;
  const i = s.window_index;
  const day = t => new Date(t).toISOString().slice(0, 10);

  const from = day(s.anchor - nbaWindows[i] * 86400000);

  const to = i === 0
    ? day(s.anchor)
    : day(
        Date.parse(
          day(s.anchor - nbaWindows[i - 1] * 86400000) +
          'T00:00:00Z'
        ) - 86400000
      );

  return (
    'https://api.balldontlie.io/v1/games' +
    '?team_ids[]=' + c.home_id +
    '&team_ids[]=' + c.away_id +
    '&start_date=' + from +
    '&end_date=' + to +
    '&per_page=100' +
    (
