      c.competition + ' · ' + clock +
        ' (Europe/Paris)'
    ];

    if (
      c.sport === 'football' ||
      c.sport === 'basketball'
    ) {
      const summaries = [];
      let olderSeasonIncluded = false;

      if (c.sport === 'basketball') {
        lines.push(
          '',
          'Recent NBA form · preseason excluded'
        );
      }

      for (
        const [side, id, name] of [
          ['home', c.home_id, c.home],
          ['away', c.away_id, c.away]
        ]
      ) {
        const games =
          c.sport === 'football'
            ? (c.form?.[side] || [])
            : (c.form?.games || []);

        const sample =
          c.sport === 'basketball'
            ? nbaSample(games, id, c)
