                .filter(g =>
                  g.status === 'FINISHED' &&
                  [g.homeTeam?.id, g.awayTeam?.id]
                    .map(String)
                    .includes(String(id)) &&
                  Date.parse(g.utcDate) < Date.now() &&
                  Number.isFinite(g.score?.fullTime?.home) &&
                  Number.isFinite(g.score?.fullTime?.away)
