        for (const g of sample) {
          const isHome =
            String(
              c.sport === 'football'
                ? g.homeTeam.id
                : g.home_team.id
            ) === String(id);

          const homeScore =
            c.sport === 'football'
              ? g.score.fullTime.home
              : g.home_team_score;

          const awayScore =
            c.sport === 'football'
              ? g.score.fullTime.away
              : g.visitor_team_score;

          const own = isHome ? homeScore : awayScore;
          const opponent = isHome ? awayScore : homeScore;

          scored += own;
          conceded += opponent;
          wins += own > opponent ? 1 : 0;
          draws += own === opponent ? 1 : 0;

          form.push(
            own > opponent
              ? 'W'
              : own === opponent
                ? 'D'
                : 'L'
          );
        }

        if (!sample.length) {
          lines.push(
            '',
            name + ': recent results unavailable.'
          );
          continue;
        }

        const n = sample.length;

        const description =
          c.sport === 'basketball' && c.form?.nba_notice
            ? 'verified recent results (' + n + ' games)'
            : 'last ' + n + ' completed games';

        lines.push(
          '',
          name + ' — ' + description + ':',
          form.join(' · ') + ' (newest first)',
          wins + 'W' +
            (c.sport === 'football' ? ' ' + draws + 'D' : '') +
            ' ' + (n - wins - draws) + 'L · average ' +
            (c.sport === 'football' ? 'goals' : 'points') +
            ': ' + (scored / n).toFixed(1) + ' for / ' +
            (conceded / n).toFixed(1) + ' against'
        );

        if (c.sport === 'basketball') {
          const dateFmt = new Intl.DateTimeFormat(
            'en-GB',
            {
              timeZone: 'Europe/Paris',
              day: '2-digit',
              month: 'short',
              year: 'numeric'
            }
          );

          lines.push(
            'Results dated ' +
            dateFmt.format(
              new Date(nbaTime(sample[sample.length - 1]))
            ) +
            ' – ' +
            dateFmt.format(new Date(nbaTime(sample[0]))) +
            '.'
          );

          const previous = [...new Set(
            sample
              .filter(g =>
                Number.isInteger(g.season) &&
                Number.isInteger(c.nba_season) &&
                g.season < c.nba_season
              )
              .map(g => g.season)
          )].sort();

          if (previous.length) {
            olderSeasonIncluded = true;

            lines.push(
              'Includes ' +
              previous
                .map(y => y + '–' + String(y + 1).slice(-2))
                .join(', ') +
              ' season results.'
            );
          }

          if (n < 5 && !c.form?.nba_notice) {
            lines.push(
              'Only ' + n +
              ' verified completed games were available ' +
              'in the searched history.'
            );
          }
        }

        summaries.push({
          name,
          n,
          rate: wins / n
        });
      }

      if (
        summaries.length === 2 &&
        summaries.every(s => s.n >= 3) &&
        !c.form?.nba_notice
      ) {
        const [a, b] = summaries;

        lines.push(
          '',
          Math.abs(a.rate - b.rate) < 0.15
            ? 'Recent win rates are similar, so the form ' +
              'sample does not point to a clear advantage.'
            : (a.rate > b.rate ? a.name : b.name) +
              ' has the stronger win rate in this recent sample. ' +
              'That is context rather than a prediction.'
        );
      }

      if (
        c.sport === 'basketball' &&
        c.form?.nba_notice
      ) {
        lines.push('', c.form.nba_notice);
      }

      if (olderSeasonIncluded) {
        lines.push(
          '',
          'Older-season results may reflect different ' +
          'rosters and are only background context.'
        );
      }
    } else {
      if (c.circuit) {
        lines.push(
          '',
          'Circuit: ' + c.circuit +
          (c.location ? ' · ' + c.location : '')
        );
      }

      const race = c.form?.race;

      if (
        race &&
