        lines.push(
          '',
          'Most recent completed Grand Prix: ' +
            race.raceName,
          ...top.map(r =>
            r.position + '. ' +
            r.Driver.givenName + ' ' +
            r.Driver.familyName + ' — ' +
            (r.Constructor?.name || '')
          )
        );
      } else {
        lines.push(
          '',
          'Previous race results are unavailable.'
