const nbaFinal = (g, c) => {
  const time = nbaTime(g);
  const cutoff = Math.min(
    c.form?.nba_search?.anchor || Date.now(),
    Date.parse(c.at)
  );

  return (
    g.id != null &&
    String(g.id) !== String(c.provider_id) &&
    g.season_type !== 'preseason' &&
    !g.postponed &&
    (
      g.status_state === 'final' ||
      (!g.status_state && /^final/i.test(g.status || ''))
    ) &&
    Number.isFinite(time) &&
    time < cutoff &&
    Number.isFinite(g.home_team_score) &&
    Number.isFinite(g.visitor_team_score) &&
    g.home_team_score >= 0 &&
