    ? day(s.anchor)
    : day(
        Date.parse(
          day(s.anchor - nbaWindows[i - 1] * 86400000) +
          'T00:00:00Z'
        ) - 86400000
      );

  return (
    'https://api.balldontlie.io/v1/games' +
    '?team_ids[]=' + c.home_id +
    '&team_ids[]=' + c.away_id +
    '&start_date=' + from +
    '&end_date=' + to +
    '&per_page=100' +
